@Override public void execute(SessionData data, Element command) {
  Element note = command.addElement("note");
  if (UserManager.getUserProvider().isReadOnly()) {
    note.addAttribute("type", "error");
    note.setText("Users are read only. Changing password is not allowed.");
    return;
  }
  JID account = new JID(data.getData().get("accountjid").get(0));
  String newPassword = data.getData().get("password").get(0);
  try {
    if (!XMPPServer.getInstance().isLocal(account)) {
      note.addAttribute("type", "error");
      note.setText("Cannot change password of remote user.");
      return;
    }
    User user = UserManager.getInstance().getUser(account.getNode());
  } catch (UserNotFoundException e) {
    note.addAttribute("type", "error");
    note.setText("User does not exist.");
    return;
  } catch (NullPointerException | ClassCastException | UnsupportedOperationException | IllegalArgumentException e) {
    note.addAttribute("type", "error");
    note.setText("An error occurred while processing the request.");
    return;
  }
  try {
    user.setPassword(newPassword);
    note.addAttribute("type", "info");
    note.setText("Operation finished successfully");
  } catch (UnsupportedOperationException e) {
    note.addAttribute("type", "error");
    note.setText("User provider is read-only. Changing password is not allowed.");
    return;
  } catch (NullPointerException | ClassCastException | IllegalArgumentException e) {
    note.addAttribute("type", "error");
    note.setText("An error occurred while setting the password.");
    return;
  }
}
